/**
 * mock rhachet-roles-test package for the hook dispatcher acceptance test
 * exports getRoleRegistry() with one role whose hooks span every dispatcher rule kind:
 *   rhx-skill (`rhx <skill>`), rhx-init (`rhachet run --init`), shell (`bash <path>`), and
 *   foreign (any other command)
 */

const INITS = '.agent/repo=test/role=tester/inits/claude.hooks';

const getRoleRegistry = () => ({
  slug: 'test',
  readme: { uri: 'readme.md' },
  roles: [
    {
      slug: 'tester',
      name: 'Tester',
      purpose: 'test role whose hooks span every dispatcher rule kind',
      readme: { uri: 'roles/tester/readme.md' },
      traits: [],
      skills: { dirs: { uri: 'roles/tester/skills' }, refs: [] },
      briefs: { dirs: { uri: 'roles/tester/briefs' } },
      inits: { dirs: { uri: 'roles/tester/inits' } },
      hooks: {
        onBrain: {
          onBoot: [
            {
              command:
                './node_modules/.bin/rhachet run --repo test --role tester --init claude.hooks/boot',
              timeout: 'PT10S',
            },
          ],
          onTool: [
            {
              command: './node_modules/.bin/rhx allow --mode hook',
              timeout: 'PT10S',
              filter: { what: 'Bash' },
            },
            {
              command: './node_modules/.bin/rhx block --mode hook',
              timeout: 'PT10S',
              filter: { what: 'Write|Bash' },
            },
            {
              command: `bash ${INITS}/trap.sh`,
              timeout: 'PT10S',
              filter: { what: 'Bash' },
            },
            {
              command: `bash ${INITS}/crash.sh`,
              timeout: 'PT10S',
              filter: { what: 'Bash' },
            },
            {
              command: `bash ${INITS}/json.sh`,
              timeout: 'PT10S',
              filter: { what: 'Bash' },
            },
            {
              command: `bash ${INITS}/hang.sh`,
              timeout: 'PT2S',
              filter: { what: 'Bash' },
            },
            {
              command: './node_modules/.bin/rhx allow --mode read',
              timeout: 'PT10S',
              filter: { what: 'Read' },
            },
          ],
          onStop: [{ command: 'echo "stop as declared"', timeout: 'PT10S' }],
        },
      },
    },
  ],
});

module.exports = { getRoleRegistry };
